create table archivos_db (          -- diseño A: los bytes adentro
  id int primary key, nombre text not null, mime text not null,
  bytes int not null, datos bytea not null);

create table archivos_ruta (         -- diseño B: la ficha; el archivo vive afuera
  id int primary key, nombre text not null, mime text not null,
  bytes int not null, sha256 text not null, ruta text not null);

// A: los bytes viajan dentro del INSERT
for (const [i, n] of nombres.entries()) {
  const b = fs.readFileSync(`${D}/uploads/${n}`);
  await c.query("insert into archivos_db values ($1,$2,'image/jpeg',$3,$4)", [i + 1, n, b.length, b]);
}
// B: el archivo va al almacén (su nombre es su hash) y la base anota la ficha
for (const [i, n] of nombres.entries()) {
  const b = fs.readFileSync(`${D}/uploads/${n}`);
  const h = crypto.createHash("sha256").update(b).digest("hex");
  fs.copyFileSync(`${D}/uploads/${n}`, `${D}/store/${h.slice(0, 2)}/${h}`);
  await c.query("insert into archivos_ruta values ($1,$2,'image/jpeg',$3,$4,$5)", [i + 1, n, b.length, h, `store/${h.slice(0, 2)}/${h}`]);
}
